/* ════════ GEO MATH ════════ */
const D2R = Math.PI / 180;
const mercX = (lng) => (lng + 180) / 360;
const mercY = (lat) => {
  const s = Math.sin(Math.max(-85, Math.min(85, lat)) * D2R);
  return 0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI);
};
const invMercLng = (x) => x * 360 - 180;
const invMercLat = (y) => {
  const n = Math.PI - 2 * Math.PI * y;
  return (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
};
function pointInLahore(lng, lat) {
  let inside = false;
  const r = LAHORE_RING;
  for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
    const xi = r[i][0], yi = r[i][1], xj = r[j][0], yj = r[j][1];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
const KM_LAT = 111.32;
const kmLng = (lat) => KM_LAT * Math.cos(lat * D2R);
const destKm = (lat, lng, km, brgDeg) => ({
  lat: lat + (km * Math.cos(brgDeg * D2R)) / KM_LAT,
  lng: lng + (km * Math.sin(brgDeg * D2R)) / kmLng(lat),
});

/* ════════ ECONOMIC ANALYSIS (sampling, auto-clipped to district) ════════ */
function densityAt(lat, lng) {
  let d = ECON.ruralBase;
  for (const n of ECON.nuclei) {
    const dx = (lng - n.lng) * kmLng(lat), dy = (lat - n.lat) * KM_LAT;
    d += n.D0 * Math.exp(-Math.sqrt(dx * dx + dy * dy) / n.lambda);
  }
  return d;
}
function analyseCircle(center, radiusKm) {
  const RINGS = 18, SECT = 20;
  let total = 0, areaIn = 0;
  for (let i = 0; i < RINGS; i++) {
    const r = ((i + 0.5) * radiusKm) / RINGS;
    const ringArea = Math.PI * (((i + 1) * radiusKm / RINGS) ** 2 - ((i * radiusKm) / RINGS) ** 2);
    let sum = 0, cnt = 0;
    for (let j = 0; j < SECT; j++) {
      const p = destKm(center.lat, center.lng, r, (j * 360) / SECT);
      if (pointInLahore(p.lng, p.lat)) { cnt++; sum += densityAt(p.lat, p.lng); }
    }
    total += (sum / SECT) * ringArea;
    areaIn += ringArea * (cnt / SECT);
  }
  return finish(total, areaIn, Math.PI * radiusKm * radiusKm);
}
function analyseRect(a, b) {
  const N = 26;
  const lat0 = Math.min(a.lat, b.lat), lat1 = Math.max(a.lat, b.lat);
  const lng0 = Math.min(a.lng, b.lng), lng1 = Math.max(a.lng, b.lng);
  const midLat = (lat0 + lat1) / 2;
  const wKm = (lng1 - lng0) * kmLng(midLat), hKm = (lat1 - lat0) * KM_LAT;
  const cell = (wKm * hKm) / (N * N);
  let total = 0, inCells = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const lat = lat0 + ((i + 0.5) / N) * (lat1 - lat0);
    const lng = lng0 + ((j + 0.5) / N) * (lng1 - lng0);
    if (pointInLahore(lng, lat)) { inCells++; total += densityAt(lat, lng) * cell; }
  }
  return finish(total, inCells * cell, wKm * hKm);
}
function finish(dailyPKRm, areaIn, areaTotal) {
  const hourly = Array.from({ length: 24 }, (_, h) =>
    ECON.sectors.reduce((a, s) => a + dailyPKRm * s.share * s.profN[h], 0));
  const bySector = ECON.sectors.map((s) => ({
    ...s, total: dailyPKRm * s.share,
    hourly: Array.from({ length: 24 }, (_, h) => dailyPKRm * s.share * s.profN[h]),
  }));
  const biz = Math.round((areaIn * 950 * (dailyPKRm / Math.max(areaIn, 0.01))) / 320);
  return {
    daily: dailyPKRm, hourly, bySector, areaIn, areaTotal,
    clippedPct: Math.max(0, 100 * (1 - areaIn / Math.max(areaTotal, 1e-9))), biz,
    peakHour: hourly.indexOf(Math.max(...hourly)),
  };
}

